import{_ as e,o as l,c as i,aw as a}from"./chunks/framework.DLufY-ao.js";const g=JSON.parse('{"title":"Задачи","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/agile/agile/tasks.md","filePath":"wiki/dev-commit/theory/agile/agile/tasks.md"}'),c={name:"wiki/dev-commit/theory/agile/agile/tasks.md"};function t(d,o,r,s,n,E){return l(),i("div",null,[...o[0]||(o[0]=[a('<h1 id="задачи" tabindex="-1">Задачи <a class="header-anchor" href="#задачи" aria-label="Permalink to &quot;Задачи&quot;">​</a></h1><h2 id="backlog" tabindex="-1">Backlog <a class="header-anchor" href="#backlog" aria-label="Permalink to &quot;Backlog&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Backlog</p><ul><li><strong>Backlog</strong> - приоритезированный список задач, куда записываются пожелания заказчика. Создают Scrum Master и Product Owner</li></ul></div><h2 id="уровни-задач" tabindex="-1">Уровни задач <a class="header-anchor" href="#уровни-задач" aria-label="Permalink to &quot;Уровни задач&quot;">​</a></h2><ol><li><strong>Epic</strong> - большая часть функционала которая может быть завершена в рамках разработки (н-р: разработка личного кабинета пользователя). Эпики делятся на Сторисы</li><li><strong>Story</strong> - более мелкая часть функционала которая еще не может случить для задач разработки (н-р: кабинет пользователя может состоять из функционала по авторизации, по рассылке уведомлений и т.д.). Сторис отвечает на вопрос &quot;Я как пользователь хочу ... (н-р: иметь возможность делать посты)&quot;</li><li><strong>Task</strong> - идут к разработчикам</li><li><strong>Sub-Task</strong> - подзадачи, идут к разработчикам</li></ol><h2 id="жизненныи-цикл-workflow-задачи" tabindex="-1">Жизненный цикл (workflow) задачи <a class="header-anchor" href="#жизненныи-цикл-workflow-задачи" aria-label="Permalink to &quot;Жизненный цикл (workflow) задачи&quot;">​</a></h2><ul><li><code>OPEN</code> - PM создал задачу</li><li><code>BACKLOG</code> - Задача без оценки</li><li><code>TODO</code> - Задача назначена на разработчика</li><li><code>IN PROGRESS</code> - Начало работы над задачей</li><li><code>BLOCKED</code> - Блокер для задачи</li><li><code>REVIEW</code> - Завершена, на ревью</li><li><code>READY FOR QA</code> - После ревью и merge в develop</li><li><code>IN QA</code> / <code>TESTING</code> - На тестировании</li><li><code>REJECTED</code> - От тестировщика в случае нахождения багов</li><li><code>IN DEV</code> - На DEV-стенде</li><li><code>READY FOR STAGE</code> - Готова к заливке на stage-стенд</li><li><code>ON STAGE</code> - На STAGE-стенде</li><li><code>PENDING RELEASE</code> - Готова к релизу</li><li><code>DONE</code> / <code>CLOSED</code> / <code>RESOLVED</code> - Закрыта</li><li><code>REOPENED</code> - PM заново открыл задачу</li></ul>',7)])])}const h=e(c,[["render",t]]);export{g as __pageData,h as default};
